def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(obj, default=(0, 0)):
        if isinstance(obj, (list, tuple)) and len(obj) >= 2:
            return obj[0], obj[1]
        return default

    def step_toward(a, b):
        ax, ay = a
        bx, by = b
        return [clamp_step(bx - ax), clamp_step(by - ay)]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position"))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    w = observation.get("grid_width", 0) or 0
    h = observation.get("grid_height", 0) or 0

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward((sx, sy), (ox, oy))
        corners = []
        if w and h:
            corners = [(0, 0), (0, h - 1), (w - 1, 0), (w - 1, h - 1)]
        else:
            corners = [(-10, -10), (-10, 10), (10, -10), (10, 10)]
        target = None
        best = None
        for c in corners:
            d = manhattan(c, (ox, oy))
            if best is None or d > best:
                best = d
                target = c
        return step_toward((sx, sy), target)

    if env == "territory_control":
        candidates = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("targets") or []
        best = None
        target = None
        for item in candidates:
            p = pos(item, None)
            if p is None:
                continue
            d = manhattan((sx, sy), p)
            if best is None or d < best:
                best = d
                target = p
        if target is not None:
            return step_toward((sx, sy), target)
        return step_toward((sx, sy), (ox, oy))

    resources = observation.get("resources") or observation.get("resource_positions") or observation.get("targets") or []
    best = None
    target = None
    for item in resources:
        p = pos(item, None)
        if p is None:
            continue
        d = manhattan((sx, sy), p)
        if best is None or d < best:
            best = d
            target = p
    if target is not None:
        return step_toward((sx, sy), target)

    return step_toward((sx, sy), (ox, oy))

